let file = """{"version":3,"file":"useCloudAuthPage-zKD7sNLP.js","names":[],"sources":["../../packages/account-ui/src/auth/SocialAuthButtons.vue","../../packages/account-ui/src/auth/SocialAuthButtons.vue","../../src/platform/cloud/onboarding/components/CloudSocialAuthButtons.vue","../../src/platform/cloud/onboarding/components/CloudSocialAuthButtons.vue","../../src/platform/cloud/onboarding/components/CloudSsoRequiredNotice.vue","../../src/platform/cloud/onboarding/components/CloudSsoRequiredNotice.vue","../../src/platform/cloud/onboarding/sso/ssoSignInState.ts","../../src/platform/cloud/onboarding/utils/previousFullPath.ts","../../src/platform/cloud/onboarding/composables/useSsoSignIn.ts","../../src/platform/cloud/oauth/useOAuthPostLoginRedirect.ts","../../src/platform/cloud/onboarding/composables/usePostAuthRedirect.ts","../../src/platform/cloud/onboarding/composables/useCloudAuthPage.ts"],"sourcesContent":["<template>\n  <button\n    type=\"button\"\n    :class=\"buttonClass\"\n    :disabled=\"disabled\"\n    @click=\"emit('google')\"\n  >\n    <svg\n      aria-hidden=\"true\"\n      viewBox=\"0 0 24 24\"\n      fill=\"currentColor\"\n      class=\"size-5 shrink-0\"\n    >\n      <path\n        d=\"M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .307 5.387.307 12s5.56 12 12.173 12c3.573 0 6.267-1.173 8.373-3.36 2.16-2.16 2.84-5.213 2.84-7.667 0-.76-.053-1.467-.173-2.053H12.48z\"\n      />\n    </svg>\n    <span :class=\"labelClass\">{{ googleLabel }}</span>\n  </button>\n\n  <button\n    type=\"button\"\n    :class=\"buttonClass\"\n    :disabled=\"disabled\"\n    @click=\"emit('github')\"\n  >\n    <svg\n      aria-hidden=\"true\"\n      viewBox=\"0 0 24 24\"\n      fill=\"currentColor\"\n      class=\"size-5 shrink-0\"\n    >\n      <path\n        d=\"M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12\"\n      />\n    </svg>\n    <span :class=\"labelClass\">{{ githubLabel }}</span>\n  </button>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The two social sign-in buttons, shared so both hosts present the same\n * providers the same way. Purely presentational: labels are host-translated,\n * the look comes through `buttonClass` and `labelClass` (each host styles\n * with its own design system), and the click handling — popup, provisioning —\n * stays with the host via the emits.\n */\nconst {\n  googleLabel,\n  githubLabel,\n  buttonClass,\n  labelClass,\n  disabled = false\n} = defineProps<{\n  googleLabel: string\n  githubLabel: string\n  buttonClass?: string\n  labelClass?: string\n  disabled?: boolean\n}>()\n\nconst emit = defineEmits<{\n  google: []\n  github: []\n}>()\n</script>\n","<template>\n  <button\n    type=\"button\"\n    :class=\"buttonClass\"\n    :disabled=\"disabled\"\n    @click=\"emit('google')\"\n  >\n    <svg\n      aria-hidden=\"true\"\n      viewBox=\"0 0 24 24\"\n      fill=\"currentColor\"\n      class=\"size-5 shrink-0\"\n    >\n      <path\n        d=\"M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .307 5.387.307 12s5.56 12 12.173 12c3.573 0 6.267-1.173 8.373-3.36 2.16-2.16 2.84-5.213 2.84-7.667 0-.76-.053-1.467-.173-2.053H12.48z\"\n      />\n    </svg>\n    <span :class=\"labelClass\">{{ googleLabel }}</span>\n  </button>\n\n  <button\n    type=\"button\"\n    :class=\"buttonClass\"\n    :disabled=\"disabled\"\n    @click=\"emit('github')\"\n  >\n    <svg\n      aria-hidden=\"true\"\n      viewBox=\"0 0 24 24\"\n      fill=\"currentColor\"\n      class=\"size-5 shrink-0\"\n    >\n      <path\n        d=\"M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12\"\n      />\n    </svg>\n    <span :class=\"labelClass\">{{ githubLabel }}</span>\n  </button>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * The two social sign-in buttons, shared so both hosts present the same\n * providers the same way. Purely presentational: labels are host-translated,\n * the look comes through `buttonClass` and `labelClass` (each host styles\n * with its own design system), and the click handling — popup, provisioning —\n * stays with the host via the emits.\n */\nconst {\n  googleLabel,\n  githubLabel,\n  buttonClass,\n  labelClass,\n  disabled = false\n} = defineProps<{\n  googleLabel: string\n  githubLabel: string\n  buttonClass?: string\n  labelClass?: string\n  disabled?: boolean\n}>()\n\nconst emit = defineEmits<{\n  google: []\n  github: []\n}>()\n</script>\n","<template>\n  <SocialAuthButtons\n    :google-label=\"googleLabel\"\n    :github-label=\"githubLabel\"\n    :button-class=\"\n      cn(\n        buttonVariants({ variant: 'brand-ghost', size: 'brand' }),\n        'w-full gap-3'\n      )\n    \"\n    label-class=\"inline-block\"\n    @google=\"emit('google')\"\n    @github=\"emit('github')\"\n  />\n\n  <p\n    v-if=\"showInAppBrowserNotice\"\n    class=\"my-0 text-xs/5 text-primary-comfy-canvas/60\"\n    data-testid=\"google-sso-in-app-browser-notice\"\n  >\n    {{ t('auth.login.googleSsoInAppBrowserNotice') }}\n  </p>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport SocialAuthButtons from '@comfyorg/account-ui/auth/SocialAuthButtons'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { buttonVariants } from '@comfyorg/design-system/button.variants'\n\nconst {\n  googleLabel,\n  githubLabel,\n  showInAppBrowserNotice = false\n} = defineProps<{\n  googleLabel: string\n  githubLabel: string\n  showInAppBrowserNotice?: boolean\n}>()\n\nconst emit = defineEmits<{\n  google: []\n  github: []\n}>()\n\nconst { t } = useI18n()\n</script>\n","<template>\n  <SocialAuthButtons\n    :google-label=\"googleLabel\"\n    :github-label=\"githubLabel\"\n    :button-class=\"\n      cn(\n        buttonVariants({ variant: 'brand-ghost', size: 'brand' }),\n        'w-full gap-3'\n      )\n    \"\n    label-class=\"inline-block\"\n    @google=\"emit('google')\"\n    @github=\"emit('github')\"\n  />\n\n  <p\n    v-if=\"showInAppBrowserNotice\"\n    class=\"my-0 text-xs/5 text-primary-comfy-canvas/60\"\n    data-testid=\"google-sso-in-app-browser-notice\"\n  >\n    {{ t('auth.login.googleSsoInAppBrowserNotice') }}\n  </p>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport SocialAuthButtons from '@comfyorg/account-ui/auth/SocialAuthButtons'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { buttonVariants } from '@comfyorg/design-system/button.variants'\n\nconst {\n  googleLabel,\n  githubLabel,\n  showInAppBrowserNotice = false\n} = defineProps<{\n  googleLabel: string\n  githubLabel: string\n  showInAppBrowserNotice?: boolean\n}>()\n\nconst emit = defineEmits<{\n  google: []\n  github: []\n}>()\n\nconst { t } = useI18n()\n</script>\n","<template>\n  <div class=\"flex flex-col gap-4\">\n    <Message severity=\"warning\">\n      {{\n        knownEmail\n          ? t('auth.sso.required.bodyWithEmail', { email: knownEmail })\n          : t('auth.sso.required.body')\n      }}\n    </Message>\n    <Button\n      type=\"button\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"w-full gap-3\"\n      :loading=\"leaving\"\n      @click=\"continueWithSso\"\n    >\n      <i class=\"icon-[lucide--building-2] size-5\" aria-hidden=\"true\" />\n      {{ t('auth.sso.continueWithSso') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { useContinueWithSso } from '@/platform/auth/sso/useContinueWithSso'\n\nconst { email, returnTo, organizationId } = defineProps<{\n  email?: string\n  returnTo?: string\n  organizationId?: string\n}>()\n\nconst { t } = useI18n()\nconst { knownEmail, leaving, continueWithSso } = useContinueWithSso(() => ({\n  email,\n  returnTo,\n  organizationId\n}))\n</script>\n","<template>\n  <div class=\"flex flex-col gap-4\">\n    <Message severity=\"warning\">\n      {{\n        knownEmail\n          ? t('auth.sso.required.bodyWithEmail', { email: knownEmail })\n          : t('auth.sso.required.body')\n      }}\n    </Message>\n    <Button\n      type=\"button\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"w-full gap-3\"\n      :loading=\"leaving\"\n      @click=\"continueWithSso\"\n    >\n      <i class=\"icon-[lucide--building-2] size-5\" aria-hidden=\"true\" />\n      {{ t('auth.sso.continueWithSso') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { useContinueWithSso } from '@/platform/auth/sso/useContinueWithSso'\n\nconst { email, returnTo, organizationId } = defineProps<{\n  email?: string\n  returnTo?: string\n  organizationId?: string\n}>()\n\nconst { t } = useI18n()\nconst { knownEmail, leaving, continueWithSso } = useContinueWithSso(() => ({\n  email,\n  returnTo,\n  organizationId\n}))\n</script>\n","import type { SsoDiscovery } from '@comfyorg/account-core/sso'\n\nexport type SsoSignInState = {\n  readonly phase:\n    | 'idle'\n    | 'checking'\n    | 'redirecting'\n    | 'not-sso'\n    | 'invalid-email'\n    | 'unavailable'\n}\n\nexport type SsoSignInEvent =\n  | { readonly type: 'submitted' }\n  | { readonly type: 'discovered'; readonly discovery: SsoDiscovery }\n  | { readonly type: 'restored' }\n\nexport const isSsoBusy = (state: SsoSignInState): boolean =>\n  state.phase === 'checking' || state.phase === 'redirecting'\n\nexport function reduceSsoSignIn(\n  state: SsoSignInState,\n  event: SsoSignInEvent\n): SsoSignInState {\n  switch (event.type) {\n    case 'submitted':\n      return isSsoBusy(state) ? state : { phase: 'checking' }\n    case 'discovered':\n      if (state.phase !== 'checking') return state\n      return event.discovery.kind === 'sso'\n        ? { phase: 'redirecting' }\n        : { phase: event.discovery.kind }\n    case 'restored':\n      return { phase: 'idle' }\n  }\n}\n","import type { LocationQuery } from 'vue-router'\n\nimport { safeInternalPath } from '@comfyorg/account-core/redirect'\n\nconst decodeQueryParam = (value: string): string | null => {\n  try {\n    return decodeURIComponent(value)\n  } catch {\n    return null\n  }\n}\n\nexport const getSafePreviousFullPath = (\n  query: LocationQuery\n): string | null => {\n  const raw = query.previousFullPath\n  const value = Array.isArray(raw) ? raw[0] : raw\n  if (!value) return null\n\n  const decoded = decodeQueryParam(value)\n  if (!decoded) return null\n\n  return safeInternalPath(decoded, window.location.origin, '') || null\n}\n","import { useEventListener } from '@vueuse/core'\nimport { computed, onScopeDispose, readonly, ref } from 'vue'\nimport type { RouteLocationNormalizedLoaded, Router } from 'vue-router'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { discoverSso, ssoStartUrl } from '@comfyorg/account-core/sso'\nimport type { SsoSurface } from '@comfyorg/account-core/telemetry'\n\nimport { toSsoReturnPath } from '@/platform/auth/sso/ssoReturnPath'\nimport {\n  trackSsoContinueClicked,\n  trackSsoSignInFailed\n} from '@/platform/auth/sso/ssoTelemetry'\n\nimport {\n  captureOAuthRequestId,\n  getOAuthRequestId\n} from '@/platform/cloud/oauth/oauthState'\nimport type {\n  SsoSignInEvent,\n  SsoSignInState\n} from '@/platform/cloud/onboarding/sso/ssoSignInState'\nimport {\n  isSsoBusy,\n  reduceSsoSignIn\n} from '@/platform/cloud/onboarding/sso/ssoSignInState'\nimport { getSafePreviousFullPath } from '@/platform/cloud/onboarding/utils/previousFullPath'\n\nconst SSO_DEFAULT_RETURN_TO = '/cloud/user-check'\n\n/**\n * Where SSO lands the person. A pending OAuth consent outranks\n * previousFullPath, as it does after a Firebase sign-in. The callback sets the\n * session cookie that the consent challenge is authenticated by, so it can land\n * on the consent page directly.\n */\nexport function resolveSsoReturnTo(\n  route: RouteLocationNormalizedLoaded,\n  router: Router\n): string {\n  const oauthRequestId =\n    captureOAuthRequestId(route.query) ?? getOAuthRequestId()\n  if (oauthRequestId) {\n    return toSsoReturnPath(\n      router.resolve({\n        name: 'cloud-oauth-consent',\n        query: { oauth_request_id: oauthRequestId }\n      }).href\n    )\n  }\n  return getSafePreviousFullPath(route.query) ?? SSO_DEFAULT_RETURN_TO\n}\n\n/** SSO sign-in for the cloud auth pages, where ingest is same-origin. */\nexport function useSsoSignIn(surface: SsoSurface) {\n  const route = useRoute()\n  const router = useRouter()\n  const state = ref<SsoSignInState>({ phase: 'idle' })\n  const dispatch = (event: SsoSignInEvent) => {\n    state.value = reduceSsoSignIn(state.value, event)\n  }\n  const busy = computed(() => isSsoBusy(state.value))\n\n  const disposal = new AbortController()\n  onScopeDispose(() => disposal.abort())\n\n  // Back from the identity provider restores this page from the bfcache with\n  // the navigation it started still showing as in flight.\n  useEventListener(window, 'pageshow', (event) => {\n    if (!event.persisted) return\n    if (state.value.phase === 'redirecting') {\n      trackSsoSignInFailed('cancelled', surface)\n    }\n    dispatch({ type: 'restored' })\n  })\n\n  /**\n   * Sends an SSO email to its identity provider. True when SSO owns the\n   * sign-in from here (a redirect, or a check already in flight); false means\n   * the caller carries on with its own sign-in.\n   */\n  async function trySso(email: string): Promise<boolean> {\n    if (busy.value) return true\n    dispatch({ type: 'submitted' })\n    const discovery = await discoverSso(email, {\n      fetchImpl: (input, init) => fetch(input, init),\n      signal: disposal.signal\n    })\n    if (disposal.signal.aborted) return true\n    dispatch({ type: 'discovered', discovery })\n    if (discovery.kind !== 'sso') return false\n    trackSsoContinueClicked(surface)\n    window.location.assign(\n      ssoStartUrl({\n        email,\n        returnTo: resolveSsoReturnTo(route, router),\n        origin: window.location.origin\n      })\n    )\n    return true\n  }\n\n  return { state: readonly(state), busy, trySso }\n}\n","import { useI18n } from 'vue-i18n'\nimport type { LocationQuery } from 'vue-router'\nimport { useRouter } from 'vue-router'\n\nimport { useSessionCookie } from '@/platform/auth/session/useSessionCookie'\nimport {\n  captureOAuthRequestId,\n  getOAuthRequestId\n} from '@/platform/cloud/oauth/oauthState'\n\ntype OAuthResumeResult =\n  | { kind: 'no-oauth' }\n  | { kind: 'resumed' }\n  | { kind: 'error'; message: string }\n\n/**\n * Post-login OAuth resume. If the current login flow originated from an OAuth\n * authorize request, establishes the Cloud session cookie and navigates to the\n * consent route. Used by both `CloudLoginView` and `CloudSignupView`.\n */\nexport function useOAuthPostLoginRedirect() {\n  const router = useRouter()\n  const sessionCookie = useSessionCookie()\n  const { t } = useI18n()\n\n  async function resumeOAuthIfNeeded(\n    query: LocationQuery\n  ): Promise<OAuthResumeResult> {\n    captureOAuthRequestId(query)\n    const oauthRequestId = getOAuthRequestId()\n    if (!oauthRequestId) return { kind: 'no-oauth' }\n\n    try {\n      await sessionCookie.createSessionOrThrow()\n    } catch (error) {\n      return {\n        kind: 'error',\n        message:\n          error instanceof Error\n            ? error.message\n            : t('oauth.consent.sessionError')\n      }\n    }\n\n    await router.push({\n      name: 'cloud-oauth-consent',\n      query: { oauth_request_id: oauthRequestId }\n    })\n    return { kind: 'resumed' }\n  }\n\n  return { resumeOAuthIfNeeded }\n}\n","import type { Ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport type { RouteLocationRaw } from 'vue-router'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { useOAuthPostLoginRedirect } from '@/platform/cloud/oauth/useOAuthPostLoginRedirect'\nimport { getSafePreviousFullPath } from '@/platform/cloud/onboarding/utils/previousFullPath'\nimport { useToast } from '@/components/ui/toast/toastStore'\n\n/**\n * Shared post-authentication redirect logic used by both CloudLoginView and\n * CloudSignupView. Handles OAuth resume, previousFullPath redirect, and\n * default redirect after successful sign-in or sign-up.\n */\nexport function usePostAuthRedirect(options: {\n  authError: Ref<string>\n  successSummary: string\n  defaultRedirect: () => RouteLocationRaw\n}) {\n  const { t } = useI18n()\n  const router = useRouter()\n  const route = useRoute()\n  const toast = useToast()\n  const { resumeOAuthIfNeeded } = useOAuthPostLoginRedirect()\n\n  async function onAuthSuccess() {\n    toast.success(options.successSummary, { duration: 2000 })\n\n    const oauthResume = await resumeOAuthIfNeeded(route.query)\n    if (oauthResume.kind === 'error') {\n      // authError renders only in email-form mode; surface the failure via\n      // a toast so social-login users (Google / GitHub) can see it too.\n      options.authError.value = oauthResume.message\n      toast.error(t('oauth.consent.sessionErrorToastSummary'), {\n        description: oauthResume.message,\n        duration: 4000\n      })\n      return\n    }\n    if (oauthResume.kind === 'resumed') return\n\n    const previousFullPath = getSafePreviousFullPath(route.query)\n    if (previousFullPath) {\n      await router.replace(previousFullPath)\n      return\n    }\n\n    await router.push(options.defaultRedirect())\n  }\n\n  return { onAuthSuccess }\n}\n","import { ref } from 'vue'\nimport type { RouteLocationRaw } from 'vue-router'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { isEmbeddedWebView } from '@comfyorg/account-core/webviewDetection'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useSessionCookie } from '@/platform/auth/session/useSessionCookie'\nimport { useSocialSignIn } from '@/platform/auth/social/useSocialSignIn'\nimport { presentSsoRequired } from '@/platform/auth/sso/ssoRequired'\nimport { useSsoRequiredInlineHost } from '@/platform/auth/sso/ssoRequiredInline'\nimport { resolveSsoReturnTo } from '@/platform/cloud/onboarding/composables/useSsoSignIn'\nimport { usePostAuthRedirect } from '@/platform/cloud/onboarding/composables/usePostAuthRedirect'\nimport { SSO_ENTRY_OPEN_QUERY } from '@/platform/cloud/onboarding/sso/ssoEntryQuery'\nimport { useAuthStore } from '@/stores/authStore'\n\ntype AuthMode = 'social' | 'email' | 'sso'\n\n/**\n * State shared by CloudLoginView and CloudSignupView. Sign-up passes\n * `isNewUser` so the provider reports the right telemetry action; the two pages\n * are otherwise identical.\n */\nexport function useCloudAuthPage(options: {\n  isNewUser?: boolean\n  successSummary: string\n  defaultRedirect: () => RouteLocationRaw\n}) {\n  const route = useRoute()\n  const router = useRouter()\n  const { flags } = useFeatureFlags()\n  const { notice: ssoRequiredNotice } = useSsoRequiredInlineHost(\n    options.isNewUser ? 'cloud_signup' : 'cloud_login'\n  )\n  const authError = ref('')\n  const authMode = ref<AuthMode>(\n    flags.ssoEnabled && route.query.sso === SSO_ENTRY_OPEN_QUERY.sso\n      ? 'sso'\n      : 'social'\n  )\n\n  const { onAuthSuccess: redirectAfterAuth } = usePostAuthRedirect({\n    authError,\n    successSummary: options.successSummary,\n    defaultRedirect: options.defaultRedirect\n  })\n\n  /**\n   * Firebase accepts an account an SSO organization holds; ingest refuses its\n   * session. That account is signed out again and sent to SSO.\n   */\n  async function onAuthSuccess() {\n    if (flags.ssoEnabled && (await useSessionCookie().sessionRequiresSso())) {\n      const authStore = useAuthStore()\n      presentSsoRequired('firebase_sign_in', {\n        email: authStore.userEmail ?? undefined,\n        returnTo: resolveSsoReturnTo(route, router)\n      })\n      await authStore.logout()\n      return\n    }\n    await redirectAfterAuth()\n  }\n\n  const social = useSocialSignIn({\n    isNewUser: () => options.isNewUser,\n    onSignedIn: onAuthSuccess\n  })\n\n  return {\n    authError,\n    authMode,\n    ssoRequiredNotice,\n    onAuthSuccess,\n    /** Snapshots, not refs: neither can change while the page is mounted. */\n    isSecureContext: globalThis.isSecureContext,\n    showGoogleS